import React, { useState } from 'react';
import axios from 'axios';
import './Auth.css';

const Dashboard = ({ user, onLogout }) => {
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [bookingSuccess, setBookingSuccess] = useState(false);
  const [bookingDetails, setBookingDetails] = useState(null);

  const movies = [
    {
      id: 1,
      title: 'Avengers: Endgame',
      genre: 'Action',
      duration: '3h 1m',
      rating: 'PG-13',
      description: 'The epic conclusion to the Infinity Saga.',
      price: 12.99
    },
    {
      id: 2,
      title: 'The Batman',
      genre: 'Action, Crime',
      duration: '2h 56m',
      rating: 'PG-13',
      description: 'The Dark Knight of Gotham City begins his war on crime.',
      price: 11.99
    },
    {
      id: 3,
      title: 'Spider-Man: No Way Home',
      genre: 'Action, Adventure',
      duration: '2h 28m',
      rating: 'PG-13',
      description: 'Spider-Man seeks the help of Doctor Strange when his secret identity is revealed.',
      price: 13.99
    },
    {
      id: 4,
      title: 'Dune',
      genre: 'Sci-Fi',
      duration: '2h 35m',
      rating: 'PG-13',
      description: 'A noble family becomes embroiled in a war for control over the galaxy\'s most valuable asset.',
      price: 12.49
    }
  ];

  const handleBookTicket = (movie) => {
    setSelectedMovie(movie);
    setBookingSuccess(false);
    setBookingDetails(null);
  };

  const confirmBooking = async () => {
    if (selectedMovie) {
      try {
        const token = localStorage.getItem('token');
        const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'http://localhost:5000';

        const bookingData = {
          userId: user.id,
          user: user.username,
          movie: selectedMovie.title,
          movieId: selectedMovie.id,
          seats: ['A1', 'A2'],
          total: selectedMovie.price * 2
        };

        console.log('Sending booking request:', bookingData);

        const response = await axios.post(`${API_BASE_URL}/api/bookings`, bookingData, {
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
          }
        });

        if (response.data.success) {
          setBookingDetails(response.data.booking);
          setBookingSuccess(true);

          setTimeout(() => {
            setSelectedMovie(null);
            setBookingSuccess(false);
          }, 5000);
        }
      } catch (error) {
        console.error('Booking API error:', error);
        // Fallback to simulated booking if API fails
        const booking = {
          id: Date.now(),
          movie: selectedMovie.title,
          user: user.username,
          date: new Date().toLocaleDateString(),
          time: '7:00 PM',
          seats: ['A1', 'A2'],
          total: selectedMovie.price * 2,
          bookingId: 'BK' + Date.now()
        };

        setBookingDetails(booking);
        setBookingSuccess(true);

        setTimeout(() => {
          setSelectedMovie(null);
          setBookingSuccess(false);
        }, 5000);
      }
    }
  };

  const cancelBooking = () => {
    setSelectedMovie(null);
    setBookingSuccess(false);
    setBookingDetails(null);
  };

  console.log('🎬 Dashboard loaded for user:', user);

  return (
    <div className="container">
      <div className="card">
        <div style={{ 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center', 
          marginBottom: '30px',
          flexWrap: 'wrap',
          gap: '20px'
        }}>
          <div>
            <h1 style={{ color: '#333', marginBottom: '10px' }}>
              Welcome to Movie Ticket App!
            </h1>
            <p style={{ color: '#666', fontSize: '18px' }}>
              Hello, <strong>{user?.username}</strong>! Ready to book some movies?
            </p>
          </div>
          <button 
            onClick={onLogout} 
            className="btn btn-secondary"
            style={{ minWidth: '120px' }}
          >
            Logout
          </button>
        </div>

        {/* Booking Success Message */}
        {bookingSuccess && bookingDetails && (
          <div className="card" style={{
            background: '#d4edda',
            border: '1px solid #c3e6cb',
            color: '#155724'
          }}>
            <h3>🎉 Booking Confirmed!</h3>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginTop: '15px' }}>
              <div><strong>Booking ID:</strong> {bookingDetails.bookingId}</div>
              <div><strong>Movie:</strong> {bookingDetails.movie}</div>
              <div><strong>Date:</strong> {bookingDetails.date}</div>
              <div><strong>Time:</strong> {bookingDetails.time}</div>
              <div><strong>Seats:</strong> {bookingDetails.seats.join(', ')}</div>
              <div><strong>Total:</strong> ${bookingDetails.total}</div>
            </div>
            <p style={{ marginTop: '15px', fontWeight: 'bold' }}>
              Enjoy your movie! 🍿
            </p>
          </div>
        )}

        {/* Booking Modal */}
        {selectedMovie && !bookingSuccess && (
          <div style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0,0,0,0.5)',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            zIndex: 1000
          }}>
            <div className="card" style={{ maxWidth: '500px', width: '90%' }}>
              <h2>Book Tickets - {selectedMovie.title}</h2>
              <div style={{ margin: '20px 0' }}>
                <p><strong>Genre:</strong> {selectedMovie.genre}</p>
                <p><strong>Duration:</strong> {selectedMovie.duration}</p>
                <p><strong>Rating:</strong> {selectedMovie.rating}</p>
                <p><strong>Price per ticket:</strong> ${selectedMovie.price}</p>
                <p><strong>Description:</strong> {selectedMovie.description}</p>
              </div>

              <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                <button 
                  className="btn btn-primary"
                  onClick={confirmBooking}
                >
                  Confirm Booking (2 tickets - ${(selectedMovie.price * 2).toFixed(2)})
                </button>
                <button 
                  className="btn btn-secondary"
                  onClick={cancelBooking}
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        )}

        <div className="card">
          <h2 style={{ marginBottom: '20px', color: '#333' }}>🎥 Now Showing</h2>
          <div style={{ 
            display: 'grid', 
            gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', 
            gap: '25px' 
          }}>
            {movies.map(movie => (
              <div 
                key={movie.id} 
                style={{
                  border: '1px solid #e1e5e9',
                  borderRadius: '15px',
                  padding: '20px',
                  textAlign: 'center',
                  background: 'white',
                  boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
                  transition: 'transform 0.2s ease, box-shadow 0.2s ease'
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.transform = 'translateY(-5px)';
                  e.currentTarget.style.boxShadow = '0 8px 15px rgba(0, 0, 0, 0.2)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = 'translateY(0)';
                  e.currentTarget.style.boxShadow = '0 4px 6px rgba(0, 0, 0, 0.1)';
                }}
              >
                <div style={{
                  width: '100%',
                  height: '200px',
                  borderRadius: '10px',
                  marginBottom: '15px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                  color: 'white',
                  fontWeight: 'bold',
                  fontSize: '16px'
                }}>
                  🎬 {movie.title}
                </div>
                <h3 style={{ 
                  marginBottom: '10px', 
                  color: '#333',
                  fontSize: '20px'
                }}>
                  {movie.title}
                </h3>
                <p style={{ color: '#666', marginBottom: '5px' }}>
                  <strong>Genre:</strong> {movie.genre}
                </p>
                <p style={{ color: '#666', marginBottom: '5px' }}>
                  <strong>Duration:</strong> {movie.duration} • <strong>Rating:</strong> {movie.rating}
                </p>
                <p style={{ color: '#666', marginBottom: '10px', fontWeight: 'bold' }}>
                  <strong>Price:</strong> ${movie.price}
                </p>
                <p style={{ 
                  color: '#888', 
                  fontSize: '14px',
                  marginBottom: '15px',
                  fontStyle: 'italic'
                }}>
                  {movie.description}
                </p>
                <button 
                  className="btn btn-primary" 
                  style={{ width: '100%' }}
                  onClick={() => handleBookTicket(movie)}
                >
                  🎟️ Book Tickets
                </button>
              </div>
            ))}
          </div>
        </div>

        <div className="card">
          <h2 style={{ marginBottom: '20px', color: '#333' }}>👤 Your Profile</h2>
          <div style={{ 
            display: 'grid', 
            gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', 
            gap: '20px',
            background: '#f8f9fa',
            padding: '20px',
            borderRadius: '10px'
          }}>
            <div style={{ padding: '15px' }}>
              <strong>Username:</strong> {user?.username}
            </div>
            <div style={{ padding: '15px' }}>
              <strong>Email:</strong> {user?.email}
            </div>
            <div style={{ padding: '15px' }}>
              <strong>User ID:</strong> {user?.id}
            </div>
            <div style={{ padding: '15px' }}>
              <strong>Status:</strong> <span style={{ color: '#28a745' }}>✓ Active</span>
            </div>
          </div>
        </div>

        <div style={{ 
          textAlign: 'center', 
          marginTop: '40px', 
          padding: '20px',
          background: '#f8f9fa',
          borderRadius: '10px'
        }}>
          <h3 style={{ color: '#666', marginBottom: '10px' }}>
            🎉 Welcome to our Movie Ticket Booking Platform!
          </h3>
          <p style={{ color: '#888' }}>
            Browse our selection of movies and book your tickets easily.
            Click "Book Tickets" on any movie to start your booking!
          </p>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
